2: 
3: export async function listItems0(db, context, input) {
4:   const recordId = input.recordId;
5:   const column = input.order === 'label' ? 'label' : 'created_at';
6:   const direction = input.direction === 'asc' ? 'ASC' : 'DESC';
7:   const statement = sql`SELECT id, label FROM items WHERE tenant_id = :tenantId AND id >= :recordId ORDER BY created_at DESC LIMIT :limit`;
8:   const params = { tenantId: context.tenantId, recordId, limit: input.limit };
9:   const query = bind(statement, params);
10:   return db.query(query.text, query.params);
11: }
